const Auth=(()=>{const s="taller_session";return{isLoggedIn:()=>!DB.settings.requirePassword||"1"===sessionStorage.getItem(s),async login(t){if(!DB.settings.requirePassword)return sessionStorage.setItem(s,"1"),!0;const e=await DB.sha256(t||"");return DB.settings.passwordHash?e===DB.settings.passwordHash&&(sessionStorage.setItem(s,"1"),!0):(DB.updateSettings({passwordHash:e}),sessionStorage.setItem(s,"1"),!0)},logout(){sessionStorage.removeItem(s)},async setPassword(s){const t=await DB.sha256(s);DB.updateSettings({passwordHash:t})},getQuestions:()=>(DB.settings.securityQuestions||[]).map(s=>s.q),async verifyAnswers(s){const t=DB.settings.securityQuestions||[];if(!t.length||s.length!==t.length)return!1;for(let e=0;e<t.length;e++)if(await DB.hashAnswer(s[e]||"")!==t[e].aHash)return!1;return!0}}})();window.Auth=Auth;